            children = mro_tree [ cls ] 
            # exactly one descendent, promote flag section 
            if len (children)== 1:
                cls = children [ 0 ] 
            newflag [ cls ] = subdict 
        flags [ key ] = (newflag,help)
    return flags,aliases


